import React from 'react';
import SlideBarComponent from '../../components/SlideBar/SlideBarComponent';
import { PieChart, Pie, Cell, Legend, Tooltip, ResponsiveContainer } from 'recharts';

const data = [
    { name: 'Cổ đông', value: 70 },
    { name: 'Không phải cổ đông', value: 30 },
];

const COLORS = ['#0088FE', '#FF8042'];

const IncomeShareholder = () => {
    return (
        <div className="flex h-screen">
            {/* Sidebar */}
            <div className="w-1/5 bg-gray-100">
                <SlideBarComponent />
            </div>

            {/* Main Content */}
            <div className="w-4/5 p-6">
                <h1 className="text-2xl font-bold mb-4">Thống kê theo cổ đông</h1>

                <div className="flex gap-6">
                    {/* Table */}
                    <div className="w-1/2">
                        <table className="w-full border border-gray-300 text-center">
                            <thead className="bg-gray-200">
                                <tr>
                                    <th className="border px-4 py-2">Loại</th>
                                    <th className="border px-4 py-2">Số lượng</th>
                                </tr>
                            </thead>
                            <tbody>
                                {data.map((item, index) => (
                                    <tr key={index}>
                                        <td className="border px-4 py-2">{item.name}</td>
                                        <td className="border px-4 py-2">{item.value}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    {/* Chart */}
                    <div className="w-1/2">
                        <ResponsiveContainer width="100%" height={300}>
                            <PieChart>
                                <Pie
                                    data={data}
                                    cx="50%"
                                    cy="50%"
                                    labelLine={false}
                                    outerRadius={100}
                                    dataKey="value"
                                    label={({ name, percent }) =>
                                        `${name}: ${(percent * 100).toFixed(0)}%`
                                    }
                                >
                                    {data.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip />
                                <Legend />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default IncomeShareholder;
